css:
.charactersim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1c2230;
    background: linear-gradient(165deg, #f3f1ec 0%, #e9e6df 100%);
    border-radius: 18px;
}

.charactersim-container * {
    box-sizing: border-box;
}

.charactersim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #14213d 0%, #23304f 55%, #2f3b5c 100%);
    color: #f6f4ee;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(20, 33, 61, 0.32);
    border-bottom: 3px solid #c79a3c;
}

.charactersim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.charactersim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e6c878;
    background: rgba(199, 154, 60, 0.16);
    padding: 5px 14px;
    border-radius: 999px;
    border: 1px solid rgba(199, 154, 60, 0.35);
}

.charactersim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d8dae3;
}

.charactersim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2c3650;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.charactersim-period-counter #currentDay,
.charactersim-period-counter #maxPeriods {
    font-weight: 800;
    color: #14213d;
}

.charactersim-round-name {
    background: #dfdac9;
    color: #14213d;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.charactersim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a2f1d;
    background: #f7e1da;
    padding: 4px 12px;
    border-radius: 999px;
}

.charactersim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.charactersim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #ddd8cc;
    box-shadow: 0 4px 14px rgba(20, 33, 61, 0.07);
    border-top: 4px solid #c79a3c;
}

.charactersim-card-balance { border-top-color: #2f6f6a; }
.charactersim-card-quality { border-top-color: #2f5fa8; }
.charactersim-card-trust { border-top-color: #6a4fa0; }
.charactersim-card-risk { border-top-color: #b5762a; }

.charactersim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6a7184;
}

.charactersim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #14213d;
}

.charactersim-card-balance .charactersim-value { color: #2f6f6a; }
.charactersim-card-quality .charactersim-value { color: #2f5fa8; }
.charactersim-card-trust .charactersim-value { color: #6a4fa0; }
.charactersim-card-risk .charactersim-value { color: #b5762a; }

.charactersim-sublabel {
    font-size: 0.75rem;
    color: #7b8295;
    line-height: 1.35;
}

/* Risk is inverted: high risk = bad (red), low risk = good (green). */
.charactersim-risk-high .charactersim-value { color: #c0392b; }
.charactersim-risk-low .charactersim-value { color: #2f6f4a; }

.charactersim-balance-strong { border-top-color: #2f6f4a; }
.charactersim-balance-strong .charactersim-value { color: #2f6f4a; }
.charactersim-balance-weak { border-top-color: #c0392b; }
.charactersim-balance-weak .charactersim-value { color: #c0392b; }

.charactersim-budget-over { border-top-color: #c0392b; }
.charactersim-budget-bar.charactersim-budget-over { background: #6e1f17; }

.charactersim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #14213d;
    color: #f1ede2;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border-left: 4px solid #c79a3c;
}

.charactersim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e6c878;
}

.charactersim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c79a3c;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(20, 33, 61, 0.05);
}

.charactersim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.charactersim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #14213d;
    margin-bottom: 6px;
}

.charactersim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #2c3346;
}

.charactersim-briefing-text strong { color: #2f6f6a; }
.charactersim-briefing-text em { color: #9a2f1d; font-style: italic; }

.charactersim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #ddd8cc;
    box-shadow: 0 4px 14px rgba(20, 33, 61, 0.07);
}

.charactersim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #14213d;
    border-bottom: 2px solid #ece8dd;
    padding-bottom: 8px;
}

.charactersim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #232c42;
    margin: 14px 0 6px;
}

.charactersim-container select,
.charactersim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cbc6b8;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #faf8f2;
    color: #1c2230;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.charactersim-container select:focus,
.charactersim-container input[type="number"]:focus {
    outline: none;
    border-color: #c79a3c;
    box-shadow: 0 0 0 3px rgba(199, 154, 60, 0.18);
}

.charactersim-container select option {
    background-color: #ffffff;
    color: #1c2230;
}

.charactersim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c79a3c;
}

.charactersim-range-readout,
.charactersim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2f5fa8;
    margin-top: 4px;
}

.charactersim-range-readout span:last-child,
.charactersim-alloc-readout span:nth-child(2) {
    color: #2f6f6a;
    font-weight: 800;
}

.charactersim-hint {
    font-size: 0.8rem;
    color: #7b8295;
    margin-top: 4px;
    line-height: 1.4;
}

.charactersim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.charactersim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f6f3ea;
    border: 1px solid #e4dfd0;
    border-radius: 9px;
    padding: 8px 12px;
}

.charactersim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #232c42;
}

.charactersim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.charactersim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.charactersim-container .btn-primary {
    background: linear-gradient(135deg, #14213d 0%, #2f3b5c 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #ffffff;
    box-shadow: 0 6px 16px rgba(20, 33, 61, 0.30);
    border-bottom: 2px solid #c79a3c;
}

.charactersim-container .btn-primary:hover {
    filter: brightness(1.12);
}

.charactersim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cbc6b8;
    color: #6a7184;
}

.charactersim-coach {
    background: #14213d;
    color: #eef0f6;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(20, 33, 61, 0.24);
    border-left: 4px solid #c79a3c;
}

.charactersim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e6c878;
    margin-bottom: 8px;
}

.charactersim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.charactersim-coach-body strong { color: #ffd98a; }
.charactersim-coach-body em { color: #f0b8a8; font-style: italic; }

.charactersim-history,
.charactersim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #ddd8cc;
    box-shadow: 0 4px 14px rgba(20, 33, 61, 0.07);
}

.charactersim-history h3,
.charactersim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #14213d;
}

.charactersim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #232c42;
}

.charactersim-container table#usfHistoryTable th {
    background: #f1eee4;
    color: #14213d;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e0dac9;
}

.charactersim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #efece2;
}

.charactersim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf8f2;
}

.charactersim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .charactersim-container {
        padding: 14px;
    }
    .charactersim-header h1 {
        font-size: 1.7rem;
    }
    .charactersim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .charactersim-value {
        font-size: 2rem;
    }
    .charactersim-clock {
        margin-left: 0;
    }
    .charactersim-period-counter {
        font-size: 0.88rem;
    }
    .charactersim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .charactersim-alloc-row {
        flex-wrap: wrap;
    }
    .charactersim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .charactersim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (light modal, charactersim) ---- */
.charactersim-completion { padding: 8px 4px 4px; }
.charactersim-cm-head { text-align: center; margin-bottom: 16px; }
.charactersim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #2f6f6a; }
.charactersim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #6a9b96; }
.charactersim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #14213d; }
.charactersim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.charactersim-cm-yes { background: rgba(47,111,106,0.14); color: #256b64; border: 1px solid rgba(47,111,106,0.5); }
.charactersim-cm-no { background: rgba(199,154,60,0.16); color: #8a6a1f; border: 1px solid rgba(199,154,60,0.5); }
.charactersim-cm-fail { background: rgba(192,57,43,0.12); color: #b0392b; border: 1px solid rgba(192,57,43,0.45); }
.charactersim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.charactersim-cm-metric { flex: 1 1 110px; min-width: 100px; background: rgba(20,33,61,0.06); border: 1px solid rgba(20,33,61,0.16); border-radius: 10px; padding: 10px 8px; text-align: center; }
.charactersim-cm-metric-risk { background: rgba(192,57,43,0.06); border-color: rgba(192,57,43,0.20); }
.charactersim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #23304f; }
.charactersim-cm-metric-risk .charactersim-cm-mv { color: #b0392b; }
.charactersim-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #5a6577; text-transform: uppercase; letter-spacing: 0.03em; }
.charactersim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #14213d; }
.charactersim-cm-insights { margin: 0; padding-left: 20px; }
.charactersim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #2b3547; }

